    def addDelete(self):
        row=self.tableWidget.currentRow()
        col=self.tableWidget.currentColumn()
        mydata=self.factordata[row]
        if col==5:
            mydata['No']+=1
            mydata['total']=mydata["No"]*mydata['price']
        elif col==6:
            mydata["No"]-=1
            mydata["total"]=mydata["No"]*mydata["price"]
            if mydata["No"]==0:
                self.factordata.pop(row)
        self.factorchange=True
        self.btnsave.setEnabled(True)
        self.filltable()           

