    def new(self,ui,Dialog):
        self.customer={
                       'id':int(ui.lineEdit_1.text()),
                       'name':ui.lineEdit_2.text(),
                       'password':ui.lineEdit.text(),
                       'pic':ui.filename
                       }   
        ui.save()  
        Dialog.close()
        self.setcustomer()

    def setcustomer(self):
        self.labelid.setText(str(self.customer.get('name',''))) 
        # self.labelname.setText(str(self.customer.get('phone','')))
        self.label_4.setPixmap(QtGui.QPixmap(self.customer.get('pic','')))
        

    def savefactor(self):
        self.factorchange=False
        self.btnsave.setEnabled(False)    
        if not self.customer.get('id'):
            self.newcustomer()    
        if self.factor['id']==-1:
            self.factor['id']=self.db.insert_factor(cid=self.customer['id'],
                                                    date=self.factor['date'])
        else:
            self.db.delete_factor_d(self.factor['id'])
        mydata=[{'fid':self.factor['id'],'pid':item['id'],'no':item['No'],'total':item['total']}for item in self.factordata]
        
        for i in mydata:
            self.db.insert_factor_d(i) 
                    

    def newfactor(self):
            self.factordata=[]
            self.filltable()
            self.customer = {'id':'', 'name':'', 'password':''}
            self.factor = {'id': -1,'date':JalaliDate.today().strftime("%Y/%m/%d")}
            self.setcustomer()
            self.comboBox1.setCurrentIndex(0)
            self.spinBox1.setValue(0)
        

    def enableadd(self):
        self.btnadd.setEnabled(self.comboBox1.currentIndex() and self.spinBox1.value()) 

            
    def fillcombo(self):
        for item in self.data:
             self.comboBox1.addItem(item['name'])
   
    def additem(self):
        index=self.comboBox1.currentIndex()
        newitem={
            'id':self.data[index]['id'],
            'name':self.comboBox1.currentText(),
            'price':self.data[index]['price'],
            'No':self.spinBox1.value()
        }         
        newitem['total']=newitem['No']* newitem['price']
        for item in self.factordata:
            if item['id'] == newitem['id']:
                item['No'] += newitem['No']
                item['total'] += newitem["total"]
                break
        else:    
            self.factordata.append(newitem)
        self.factorchange=True
        self.comboBox1.setCurrentIndex(0)
        self.spinBox1.setValue(0)
        self.filltable()

